"""A thread-safe cache with a time to live, single-flight loads and optional bounds and stale serving.

All state is guarded by one lock. The loader is never called while the lock is held, and waiting is done on a
condition variable, which releases the lock while blocked. See docs/CONTRACT.md for the guarantees.
"""
import threading
import time
from collections import OrderedDict

from .stats import Stats


class DeadlockError(RuntimeError):
    """A get would have waited in a cycle of threads that wait for each other's loads."""


class _Entry:
    __slots__ = ("value", "loaded_at")

    def __init__(self, value, loaded_at):
        self.value = value
        self.loaded_at = loaded_at


class _Load:
    """One load in flight. Changed only while the cache lock is held."""

    __slots__ = ("owner", "done", "value", "error", "stale")

    def __init__(self, owner):
        self.owner = owner      # thread id of the thread running the loader
        self.done = False
        self.value = None       # the stored value, or the stale value when `stale` is set
        self.error = None       # the loader's exception, when the load failed
        self.stale = False      # True when the failure is answered with a stale entry


class TTLCache:
    def __init__(self, loader, ttl, clock=time.monotonic, max_size=None, stale_grace=None):
        if not ttl > 0:
            raise ValueError("ttl must be positive")
        if max_size is not None and (
            isinstance(max_size, bool) or not isinstance(max_size, int) or max_size < 1
        ):
            raise ValueError("max_size must be None or an integer of at least 1")
        if stale_grace is not None and (
            isinstance(stale_grace, bool) or not isinstance(stale_grace, (int, float)) or not stale_grace > 0
        ):
            raise ValueError("stale_grace must be None or a number greater than zero")
        self._loader = loader
        self._ttl = ttl
        self._clock = clock
        self._max_size = max_size
        self._stale_grace = stale_grace
        self._lock = threading.Lock()
        self._changed = threading.Condition(self._lock)
        self._entries = OrderedDict()  # key -> _Entry, least recently used first
        self._loads = {}               # key -> _Load in flight
        self._waiting = {}             # thread id -> _Load that thread is blocked on
        self._stats = Stats()

    # Public API

    def get(self, key, timeout=None):
        if timeout is not None and timeout < 0:
            raise ValueError("timeout must not be negative")
        me = threading.get_ident()
        with self._changed:
            entry = self._entries.get(key)
            if entry is not None and self._clock() - entry.loaded_at < self._ttl:
                self._entries.move_to_end(key)
                self._stats.hits += 1
                return entry.value
            self._stats.misses += 1
            load = self._loads.get(key)
            if load is None:
                load = _Load(me)
                self._loads[key] = load
                self._stats.loads += 1
                owns_load = True
            else:
                owns_load = False
                if load.owner == me:
                    raise RuntimeError(f"get({key!r}) called from inside the loader for the same key")
                if self._completes_cycle(me, load):
                    self._stats.deadlocks += 1
                    raise DeadlockError(f"waiting for {key!r} would deadlock with other threads")
                if timeout == 0:
                    self._stats.timeouts += 1
                    raise TimeoutError(f"load for {key!r} is still in flight")
                return self._wait(me, key, load, timeout)
        if owns_load:
            return self._run(key, load)
        return None  # not reached

    def invalidate(self, key):
        with self._changed:
            self._entries.pop(key, None)

    def invalidate_all(self):
        with self._changed:
            removed = len(self._entries)
            self._entries.clear()
            return removed

    def stats(self, extended=False):
        with self._changed:
            return self._stats.snapshot(extended)

    def __len__(self):
        with self._changed:
            return len(self._entries)

    # Internals. Methods named _locked are called with the lock held.

    def _run(self, key, load):
        """Run the loader for `load`, which this thread owns, and publish the result."""
        try:
            value = self._loader(key)
        except BaseException as exc:
            with self._changed:
                self._stats.failures += 1
                del self._loads[key]
                load.done = True
                if isinstance(exc, Exception):
                    self._use_stale_locked(key, load)
                if not load.stale:
                    load.error = exc
                self._changed.notify_all()
                return self._outcome_locked(load)
        loaded_at = self._clock()
        with self._changed:
            del self._loads[key]
            load.value = value
            load.done = True
            self._entries[key] = _Entry(value, loaded_at)
            self._entries.move_to_end(key)
            self._evict_locked()
            self._changed.notify_all()
        return value

    def _use_stale_locked(self, key, load):
        """Mark `load` as answered with the stale entry for `key`, if there is one."""
        if self._stale_grace is None:
            return
        entry = self._entries.get(key)
        if entry is None:
            return
        age = self._clock() - entry.loaded_at
        if self._ttl <= age < self._ttl + self._stale_grace:
            load.stale = True
            load.value = entry.value

    def _wait(self, me, key, load, timeout):
        """Block until `load` finishes or `timeout` expires. Called with the lock held."""
        self._waiting[me] = load
        try:
            finished = self._changed.wait_for(lambda: load.done, timeout)
        finally:
            del self._waiting[me]
        if not finished:
            self._stats.timeouts += 1
            raise TimeoutError(f"timed out waiting for the load of {key!r}")
        return self._outcome_locked(load)

    def _outcome_locked(self, load):
        if load.error is not None:
            raise load.error
        if load.stale:
            self._stats.stale_served += 1
        return load.value

    def _completes_cycle(self, me, load):
        """True if `me` waiting for `load` closes a cycle of threads waiting for each other."""
        owner = load.owner
        seen = set()
        while owner != me:
            if owner in seen:
                return False
            seen.add(owner)
            blocked_on = self._waiting.get(owner)
            # A load that is already done no longer blocks its waiters: they are about to wake up.
            if blocked_on is None or blocked_on.done:
                return False
            owner = blocked_on.owner
        return True

    def _evict_locked(self):
        if self._max_size is None:
            return
        excess = len(self._entries) - self._max_size
        if excess <= 0:
            return
        victims = []
        for key in self._entries:  # least recently used first
            if key in self._loads:
                continue  # a key with a load in flight is never evicted
            victims.append(key)
            if len(victims) == excess:
                break
        for key in victims:
            del self._entries[key]
        self._stats.evictions += len(victims)

"""Plain counters. The cache decides when to update them."""


class Stats:
    def __init__(self):
        self.hits = 0
        self.misses = 0
        self.loads = 0
        self.failures = 0

    def snapshot(self):
        return {"hits": self.hits, "misses": self.misses, "loads": self.loads, "failures": self.failures}
